/*
 * A038988  Primes p such that 97 is not a square mod p.
 * https://oeis.org/A038988
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   primes p such that 97 is not a quadratic residue modulo p (i.e.,
 *            97 is not a square mod p). The sequence is generated by testing
 *            primes in ascending order and keeping those for which p mod 97
 *            is a non‑residue modulo 97. The residue table for 97 is
 *            precomputed once. The function is memoised so tha...
 * Range:     u8 n <= 29, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include "../utils/is_prime_big.h"

static bool residue[97] = {0};
static bool residue_inited = false;

static void
init_residue(void)
{
    if (residue_inited)
        return;
    for (int i = 1; i < 97; ++i) {
        residue[(i * i) % 97] = true;
    }
    residue_inited = true;
}

/* Storage for the terms of the sequence. */
static seq_t *cache        = NULL;
static size_t cache_len    = 0;
static size_t cache_cap    = 0;

/* Storage for the next candidate prime to test.  We start at 3.  */
static seq_t next_candidate = 3;

/* Increase the capacity of the cache. */
static void
ensure_cache_capacity(void)
{
    if (cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp)
            abort();        /* Out of memory – program terminates. */
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* Main function requested by the exercise. */
seq_t
a(idx_t n)
{
    if (n == 0)
        return 0; /* Undefined for n=0; can be ignored. */

    init_residue();

    /* Grow the cache until we have at least n terms. */
    while (cache_len < (size_t)n) {
        seq_t p = next_candidate;

        /* Find the next prime. */
        while (!is_prime_big(p))
            p += 2;

        /* Skip the modulus itself, because 97 ≡ 0² (mod 97). */
        if (p != 97) {
            seq_t mod = p % 97;
            if (!residue[(int)mod]) {
                ensure_cache_capacity();
                cache[cache_len++] = p;
            }
        }

        next_candidate = p + 2;
    }

    return cache[n - 1];
}
